// Собираем настройки system_settings в один объект
const settings = {};
for (const item of $input.all()) {
  const key = item.json.setting_key;
  if (!key) continue;
  settings[key] = item.json.setting_value;
}

if (!settings.admin_chat_id) {
  throw new Error('В system_settings не найден admin_chat_id');
}
if (!settings.supabase_url) {
  throw new Error('В system_settings не найден supabase_url');
}

return [{
  json: {
    admin_chat_id: String(settings.admin_chat_id),
    days_before_ideas: Number(settings.days_before_ideas || 21),
    supabase_url: String(settings.supabase_url).replace(/\/$/, ''),
    default_channel_name: settings.default_channel_name || '',
    ai_prompt_ideas_selector: settings.ai_prompt_ideas_selector || '',
    ai_prompt_post_generator: settings.ai_prompt_post_generator || ''
  }
}];

const allPosts = $('Aggregate Source Posts').first().json.data || [];
const chatId = String($('Prepare Curation Inputs').first().json.chat_id || '');
const daysBefore = Number($('Prepare Curation Inputs').first().json.days_before || 21);

const usedPostIds = new Set();
try {
  for (const item of $('Get Chat History').all()) {
    const message = item.json?.message || {};
    const content = String(message.content || message || '');
    for (const match of content.matchAll(/"post_id"\s*:\s*(\d+)/g)) {
      usedPostIds.add(Number(match[1]));
    }
  }
} catch (e) {}

const ECONOMY_KEYWORDS = [
  'экономика','экономический','макроэкономика','ключевая ставка','ставка цб',
  'банк россии','цб рф','центробанк','инфляция','ввп','валовый внутренний продукт',
  'инвестиции','инвесторы','фондовый рынок','облигации','офз','рубль','курс рубля',
  'финансы','бюджет','минэкономразвития','промышленность','денежно-кредитная политика'
];
const TAX_KEYWORDS = [
  'налог','налоги','фнс','ндс','усн','декларация','бухгалтерия','отчетность',
  'страховые взносы','взносы','штраф','штрафы','самозаняты'
];

function norm(value) {
  return String(value || '').toLowerCase().replace(/ё/g, 'е').replace(/\s+/g, ' ').trim();
}
function hasAny(text, words) {
  const t = norm(text);
  return words.some(word => t.includes(norm(word)));
}

const newPosts = allPosts.filter(post => {
  const id = Number(post.id);
  if (!id || usedPostIds.has(id)) return false;
  const category = norm(post.category);
  const combined = `${post.title || ''} ${post.content || ''} ${post.external_url || ''}`;
  if (category === 'tax') return false;
  if (hasAny(combined, TAX_KEYWORDS) && !hasAny(combined, ECONOMY_KEYWORDS)) return false;
  return hasAny(`${category} ${combined}`, ECONOMY_KEYWORDS);
});

return [{
  json: {
    source_type: 'supabase_candidates',
    chat_id: chatId,
    days_before: daysBefore,
    used_posts_count: usedPostIds.size,
    new_posts: newPosts.slice(0, 15),
    stats: { total: allPosts.length, available_new: newPosts.length }
  }
}];

const response = $input.first().json;
let content = response.output || response.text || response.message?.content || response.data || '';
if (typeof content !== 'string') content = JSON.stringify(content);
content = content.replace(/```json/gi, '').replace(/```/g, '').trim();

let parsed;
const objectMatch = content.match(/\{[\s\S]*\}/);
const arrayMatch = content.match(/\[[\s\S]*\]/);
try {
  if (objectMatch) parsed = JSON.parse(objectMatch[0]);
  else if (arrayMatch) parsed = { posts: JSON.parse(arrayMatch[0]) };
  else throw new Error('JSON не найден');
} catch (e) {
  throw new Error('Не удалось распарсить ответ AI Supabase: ' + content.slice(0, 1000) + '\n' + e.message);
}
if (Array.isArray(parsed)) parsed = { posts: parsed };
if (!Array.isArray(parsed.posts)) throw new Error('В ответе AI Supabase нет массива posts');

const posts = parsed.posts.slice(0, 3).map((post, index) => {
  const postId = Number(post.post_id || post.id || post.source_content_id);
  if (!postId) throw new Error(`Supabase идея ${index + 1}: нет post_id`);
  return {
    post_id: postId,
    source_type: 'supabase',
    source_name: post.source_name || 'Supabase',
    category: post.category || 'Экономика',
    title: post.title || `Идея ${index + 1}`,
    content: post.content || post.description || post.summary || '',
    views_count: Number(post.views_count || 0),
    likes_count: Number(post.likes_count || 0),
    importance_score: Number(post.importance_score || 0),
    published_at: post.published_at || null,
    external_url: post.external_url || post.source_url || '',
    why_recommended: post.why_recommended || 'Полезно для предпринимателя'
  };
});

return [{ json: {
  source_type: 'supabase',
  chat_id: String($('Prepare Curation Inputs').first().json.chat_id || ''),
  posts
} }];

function extractPayload(value) {
  if (typeof value === 'string') return value;
  if (!value || typeof value !== 'object') return '';

  if (typeof value.data === 'string') return value.data;
  if (typeof value.body === 'string') return value.body;
  if (typeof value.response === 'string') return value.response;

  if (value.data && typeof value.data === 'object') {
    return JSON.stringify(value.data);
  }
  if (value.body && typeof value.body === 'object') {
    return JSON.stringify(value.body);
  }

  return JSON.stringify(value);
}

function decodeXml(value) {
  return String(value || '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/gi, '$1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&apos;/gi, "'")
    .replace(/&#39;/gi, "'")
    .replace(/&nbsp;/gi, ' ')
    .replace(/&#x([0-9a-f]+);/gi, (_, hex) => {
      try { return String.fromCodePoint(parseInt(hex, 16)); } catch { return ''; }
    })
    .replace(/&#(\d+);/g, (_, num) => {
      try { return String.fromCodePoint(parseInt(num, 10)); } catch { return ''; }
    })
    .replace(/\s+/g, ' ')
    .trim();
}

function getTag(block, names) {
  for (const name of names) {
    const safe = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const match = block.match(
      new RegExp(`<${safe}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${safe}>`, 'i')
    );
    if (match?.[1]) return match[1];
  }
  return '';
}

function getLink(block) {
  const normal = getTag(block, ['link', 'guid', 'id']);
  if (normal) {
    const decoded = decodeXml(normal);
    const urlMatch = decoded.match(/https?:\/\/[^\s"'<>]+/i);
    if (urlMatch) return urlMatch[0];
  }

  const atom = block.match(/<link\b[^>]*\bhref=["']([^"']+)["'][^>]*\/?>/i);
  if (atom?.[1]) return decodeXml(atom[1]);

  const anyUrl = block.match(/https?:\/\/[^\s"'<>]+/i);
  return anyUrl?.[0] ? decodeXml(anyUrl[0]) : '';
}

function parseFeed(xml, sourceName, limit = 30) {
  if (!xml || typeof xml !== 'string') return [];

  let blocks = [...xml.matchAll(/<item\b[^>]*>([\s\S]*?)<\/item>/gi)]
    .map(match => match[1]);

  if (!blocks.length) {
    blocks = [...xml.matchAll(/<entry\b[^>]*>([\s\S]*?)<\/entry>/gi)]
      .map(match => match[1]);
  }

  const result = [];

  for (const block of blocks) {
    const title = decodeXml(getTag(block, ['title']));
    const link = getLink(block);
    const description = decodeXml(
      getTag(block, ['description', 'content:encoded', 'summary', 'content'])
    ).slice(0, 1200);

    const dateRaw = decodeXml(
      getTag(block, ['pubDate', 'dc:date', 'published', 'updated', 'date'])
    );

    if (!title || title.length < 5) continue;
    if (!/^https?:\/\//i.test(link)) continue;

    let publishedAt = null;
    let timestamp = 0;

    if (dateRaw) {
      const parsedDate = new Date(dateRaw);
      if (!Number.isNaN(parsedDate.getTime())) {
        timestamp = parsedDate.getTime();
        publishedAt = parsedDate.toISOString();
      }
    }

    const ageHours = timestamp
      ? (Date.now() - timestamp) / 3600000
      : null;

    result.push({
      title,
      link,
      description,
      source: sourceName,
      published_at: publishedAt,
      timestamp,
      is_fresh: ageHours === null || ageHours <= 96
    });

    if (result.length >= limit) break;
  }

  return result;
}

const feeds = [
  {
    source: 'РБК',
    payload: extractPayload($('RSS: RBC').first().json)
  },
  {
    source: 'Коммерсантъ',
    payload: extractPayload($('RSS: Kommersant').first().json)
  },
  {
    source: 'Интерфакс',
    payload: extractPayload($('RSS: Interfax').first().json)
  },
  {
    source: 'Ведомости',
    payload: extractPayload($('RSS: Vedomosti').first().json)
  }
];

let allNews = [];
const feedDiagnostics = [];

for (const feed of feeds) {
  const parsed = parseFeed(feed.payload, feed.source, 30);
  allNews.push(...parsed);

  feedDiagnostics.push({
    source: feed.source,
    payload_length: feed.payload.length,
    parsed_count: parsed.length
  });
}

if (!allNews.length) {
  throw new Error(
    'Ни один RSS не удалось распарсить. Диагностика: ' +
    JSON.stringify(feedDiagnostics)
  );
}

const shownUrls = new Set();
try {
  for (const item of $('Get Chat History').all()) {
    const content = String(
      item.json?.message?.content ||
      item.json?.message ||
      item.json?.content ||
      ''
    );

    for (const match of content.matchAll(/https?:\/\/[^"'\s\\]+/g)) {
      shownUrls.add(match[0].replace(/[?#].*$/, '').replace(/\/$/, ''));
    }
  }
} catch (e) {}

function normalizeUrl(value) {
  return String(value || '')
    .trim()
    .replace(/&amp;/gi, '&')
    .replace(/[?#].*$/, '')
    .replace(/\/$/, '');
}

const seenUrls = new Set();
const seenTitles = new Set();

allNews = allNews.filter(item => {
  const urlKey = normalizeUrl(item.link);
  const titleKey = item.title
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[^а-яa-z0-9]/gi, '')
    .slice(0, 80);

  if (!urlKey || seenUrls.has(urlKey)) return false;
  if (titleKey && seenTitles.has(titleKey)) return false;

  seenUrls.add(urlKey);
  if (titleKey) seenTitles.add(titleKey);
  return true;
});

allNews = allNews.map(item => ({
  ...item,
  already_shown: shownUrls.has(normalizeUrl(item.link))
}));

allNews.sort((a, b) => {
  const shownDiff =
    Number(Boolean(a.already_shown)) -
    Number(Boolean(b.already_shown));
  if (shownDiff !== 0) return shownDiff;

  const freshDiff =
    Number(Boolean(b.is_fresh)) -
    Number(Boolean(a.is_fresh));
  if (freshDiff !== 0) return freshDiff;

  return (b.timestamp || 0) - (a.timestamp || 0);
});

if (allNews.length < 4) {
  throw new Error(
    `RSS вернули только ${allNews.length} подходящих новостей. ` +
    `Диагностика: ${JSON.stringify(feedDiagnostics)}`
  );
}

const newsList = allNews.map((item, index) => [
  `${index + 1}. [${item.source}] ${item.title}`,
  `Описание RSS: ${item.description || 'нет описания'}`,
  `Дата: ${item.published_at || 'не указана'}`,
  `URL: ${item.link}`,
  `Свежая: ${item.is_fresh ? 'ДА' : 'НЕТ'}`,
  `Уже показывали: ${item.already_shown ? 'ДА' : 'НЕТ'}`
].join('\n')).join('\n\n');

return [{
  json: {
    newsList,
    allNews,
    sourcesFound: [...new Set(allNews.map(item => item.source))],
    feedDiagnostics
  }
}];

parameters.text:
=Из списка ниже выбери РОВНО 4 разные новости.

СПИСОК:
{{ $json.newsList }}

Правила:
- используй только новости из предоставленного списка;
- верни ровно 4 объекта;
- не выдумывай заголовки, URL, источники и даты;
- по возможности выбирай новости из разных источников;
- если один источник не отдал подходящих новостей, разрешается взять две новости другого источника;
- сначала выбирай новости, где «Уже показывали: НЕТ»;
- затем отдавай приоритет новостям, где «Свежая: ДА»;
- выбирай темы, полезные российскому предпринимателю: экономика, бизнес, финансы, банки, ключевая ставка, инфляция, ВВП, инвестиции, промышленность, законы и регулирование;
- исключай СВО, спорт, культуру, происшествия и зарубежную геополитику как главную тему;
- description: 2-3 предложения, что произошло и почему это важно для бизнеса;
- full: дополнительный контекст для генерации будущего поста.

Верни ТОЛЬКО валидный JSON-массив без markdown и пояснений:
[
  {
    "title": "точный заголовок из списка",
    "description": "2-3 предложения",
    "full": "дополнительный контекст",
    "source_name": "точное название источника из списка",
    "source_url": "точный URL из списка",
    "published_at": "ISO-дата или null"
  }
]

