const response = $input.first().json;
let content =
  response.text ||
  response.output ||
  response.message?.content ||
  '';

if (typeof content !== 'string') {
  content = JSON.stringify(content);
}

content = content
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let modelRows = [];

const jsonMatch = content.match(/\[[\s\S]*\]/);
if (jsonMatch) {
  try {
    const parsed = JSON.parse(jsonMatch[0]);
    if (Array.isArray(parsed)) modelRows = parsed;
  } catch (e) {
    // При ошибке разбора список будет собран напрямую из RSS.
  }
}

let original = [];
try {
  original = $('Parse RSS Items').first().json.allNews || [];
} catch (e) {}

if (!Array.isArray(original)) original = [];

if (original.length < 4) {
  throw new Error(
    `После парсинга доступно только ${original.length} RSS-новостей`
  );
}

function normalizeUrl(value) {
  return String(value || '')
    .trim()
    .replace(/&amp;/gi, '&')
    .replace(/[?#].*$/, '')
    .replace(/\/$/, '');
}

function normalizeTitle(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[^а-яa-z0-9]/gi, '')
    .slice(0, 120);
}

const originalByUrl = new Map();
const originalByTitle = new Map();

for (const item of original) {
  const urlKey = normalizeUrl(
    item.link ||
    item.external_url ||
    item.source_url
  );

  const titleKey = normalizeTitle(item.title);

  if (urlKey) originalByUrl.set(urlKey, item);
  if (titleKey && !originalByTitle.has(titleKey)) {
    originalByTitle.set(titleKey, item);
  }
}

function findOriginal(row) {
  const urlKey = normalizeUrl(
    row.source_url ||
    row.url ||
    row.link
  );

  if (urlKey && originalByUrl.has(urlKey)) {
    return originalByUrl.get(urlKey);
  }

  const titleKey = normalizeTitle(row.title);
  if (titleKey && originalByTitle.has(titleKey)) {
    return originalByTitle.get(titleKey);
  }

  return null;
}

function makePost(item, modelRow = null) {
  const url = String(
    item.link ||
    item.external_url ||
    item.source_url ||
    ''
  ).trim();

  return {
    source_type: 'rss',
    source_name: item.source || modelRow?.source_name || 'RSS',
    title: String(item.title || modelRow?.title || '').trim(),
    content: String(
      modelRow?.description ||
      modelRow?.short ||
      item.description ||
      'Свежая новость из RSS.'
    ).trim(),
    full: String(
      modelRow?.full ||
      modelRow?.description ||
      item.description ||
      item.title ||
      ''
    ).trim(),
    external_url: url,
    published_at:
      item.published_at ||
      modelRow?.published_at ||
      null,
    category: 'economy',
    already_shown: Boolean(item.already_shown),
    is_fresh: item.is_fresh !== false
  };
}

const selected = [];
const selectedUrls = new Set();
const usedSources = new Set();
let acceptedFromModel = 0;

for (const row of modelRows) {
  const originalItem = findOriginal(row);
  if (!originalItem) continue;

  const urlKey = normalizeUrl(originalItem.link);
  if (!urlKey || selectedUrls.has(urlKey)) continue;

  const post = makePost(originalItem, row);
  selected.push(post);
  selectedUrls.add(urlKey);
  usedSources.add(post.source_name);
  acceptedFromModel++;

  if (selected.length >= 4) break;
}

// Если модель вернула меньше четырёх реальных новостей,
// автоматически дополняем список из RSS.
while (selected.length < 4) {
  const remaining = original.filter(item => {
    const urlKey = normalizeUrl(item.link);
    return urlKey && !selectedUrls.has(urlKey);
  });

  if (!remaining.length) break;

  remaining.sort((a, b) => {
    const aNewSource = usedSources.has(a.source) ? 0 : 1;
    const bNewSource = usedSources.has(b.source) ? 0 : 1;
    if (bNewSource !== aNewSource) return bNewSource - aNewSource;

    const aNotShown = a.already_shown ? 0 : 1;
    const bNotShown = b.already_shown ? 0 : 1;
    if (bNotShown !== aNotShown) return bNotShown - aNotShown;

    const aFresh = a.is_fresh === false ? 0 : 1;
    const bFresh = b.is_fresh === false ? 0 : 1;
    if (bFresh !== aFresh) return bFresh - aFresh;

    const aTime = new Date(a.published_at || 0).getTime() || 0;
    const bTime = new Date(b.published_at || 0).getTime() || 0;
    return bTime - aTime;
  });

  const item = remaining[0];
  const post = makePost(item);

  selected.push(post);
  selectedUrls.add(normalizeUrl(item.link));
  usedSources.add(post.source_name);
}

if (selected.length !== 4) {
  throw new Error(
    `Не удалось собрать 4 RSS-новости. Собрано: ${selected.length}`
  );
}

return [{
  json: {
    source_type: 'rss_selected',
    posts: selected.map(({ already_shown, is_fresh, ...post }) => post),
    accepted_from_perplexity: acceptedFromModel,
    filled_directly_from_rss: 4 - acceptedFromModel,
    available_sources: [...new Set(original.map(item => item.source))]
  }
}];

const selected = $input.first().json.posts || [];
if (!Array.isArray(selected) || selected.length !== 4) {
  throw new Error('Для записи в source_content требуется ровно 4 RSS-новости');
}

function hash32(text) {
  let h = 100000001;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return ((h >>> 0) % 100000001) || 1;
}

const now = new Date().toISOString();
const rows = selected.map(item => ({
  platform: 'website',
  title: item.title || 'Без названия',
  content: [item.content, item.full].filter(Boolean).join('\n\n') || item.title || 'Без описания',
  external_id: hash32(item.external_url),
  external_url: item.external_url,
  views_count: 0,
  likes_count: 0,
  published_at: item.published_at || now,
  parsed_at: now,
  category: item.category || 'economy'
}));

return [{ json: {
  selected,
  insert_body: JSON.stringify(rows)
} }];

const selected = $('Parse 4 RSS Topics').first().json.posts || [];
const rawItems = $input.all().map(i => i.json);
const inserted = [];

function collect(value) {
  if (!value) return;
  if (Array.isArray(value)) { value.forEach(collect); return; }
  if (Array.isArray(value.body)) { value.body.forEach(collect); return; }
  if (Array.isArray(value.data)) { value.data.forEach(collect); return; }
  if (value.id) inserted.push(value);
}
rawItems.forEach(collect);

const byUrl = new Map(inserted.map(row => [String(row.external_url || ''), row]));
const posts = selected.map((item, index) => {
  const row = byUrl.get(String(item.external_url)) || inserted[index];
  const id = Number(row?.id);
  if (!id) throw new Error(`RSS идея ${index + 1} не получила id из source_content`);
  return {
    post_id: id,
    source_type: 'rss',
    source_name: item.source_name || 'RSS',
    category: item.category || 'economy',
    title: item.title,
    content: item.content || item.full || '',
    why_recommended: item.content || 'Свежая новость для предпринимателя',
    published_at: item.published_at || row?.published_at || null,
    external_url: item.external_url,
    views_count: 0,
    likes_count: 0,
    importance_score: 0
  };
});

return [{ json: {
  source_type: 'rss',
  chat_id: String($('Prepare Curation Inputs').first().json.chat_id || ''),
  posts
} }];

const inputs = $input.all().map(i => i.json);
const rssBlock = inputs.find(x => x.source_type === 'rss') || {};
const supabaseBlock = inputs.find(x => x.source_type === 'supabase') || {};

const rss = Array.isArray(rssBlock.posts) ? rssBlock.posts.slice(0, 4) : [];
const supabase = Array.isArray(supabaseBlock.posts) ? supabaseBlock.posts.slice(0, 3) : [];
const posts = [...rss, ...supabase].map((post, index) => ({ ...post, idea_number: index + 1 }));

if (rss.length !== 4) throw new Error(`Ожидалось 4 RSS-идеи, получено ${rss.length}`);
if (supabase.length === 0) throw new Error('Supabase не вернул ни одной идеи');

return [{ json: {
  chat_id: String(supabaseBlock.chat_id || rssBlock.chat_id || $('Prepare Curation Inputs').first().json.chat_id || ''),
  posts,
  rss_count: rss.length,
  supabase_count: supabase.length
} }];

const input = $input.first().json;
const posts = Array.isArray(input.posts) ? input.posts.slice(0, 7) : [];
const chat_id = String(input.chat_id || '');
if (!chat_id) throw new Error('Нет chat_id для Telegram');

function esc(value) {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#039;');
}
function cut(value, max = 210) {
  const text = String(value ?? '').trim();
  return text.length <= max ? text : text.slice(0, max - 1).trimEnd() + '…';
}
function formatDate(value) {
  if (!value) return '';
  const d = new Date(value);
  if (isNaN(d.getTime())) return '';
  return d.toLocaleString('ru-RU', {
    timeZone: 'Europe/Moscow', day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit'
  }) + ' МСК';
}

let text = '<b>⚡️ 7 идей на сегодня: 4 свежие новости + 3 из базы</b>\n\n';
posts.forEach((post, index) => {
  const isRss = post.source_type === 'rss';
  const marker = isRss ? '📰' : '🗄';
  const source = isRss ? `RSS - ${post.source_name || 'Источник'}` : 'Supabase';
  text += `<b>${marker} Идея ${index + 1} - ${esc(source)}</b>\n`;
  text += `<b>${esc(post.title || `Идея ${index + 1}`)}</b>\n`;
  const description = cut(post.content || post.why_recommended || '', 210);
  if (description) text += `<i>${esc(description)}</i>\n`;
  const date = formatDate(post.published_at);
  if (date) text += `📅 ${esc(date)}\n`;
  const url = String(post.external_url || '').trim();
  if (url.startsWith('http')) text += `🔗 <a href="${esc(url)}">Читать оригинал</a>\n`;
  text += '━━━━━━━━━━━━\n\n';
});
text += '👇 <b>Что берем в работу?</b>';

function bText(i) { return posts[i]?.post_id ? `📝 Идея ${i + 1}` : `⛔️ Нет идеи ${i + 1}`; }
function bCallback(i) { return posts[i]?.post_id ? `generate_post:${posts[i].post_id}` : `no_idea:${i + 1}`; }

const result = { chat_id, text, posts };
for (let i = 0; i < 7; i++) {
  result[`button${i + 1}_text`] = bText(i);
  result[`button${i + 1}_callback`] = bCallback(i);
}
result.button8_text = '🔍 Искать другие';
result.button8_callback = 'search_more';
result.reply_markup = {
  inline_keyboard: [
    [{ text: bText(0), callback_data: bCallback(0) }, { text: bText(1), callback_data: bCallback(1) }],
    [{ text: bText(2), callback_data: bCallback(2) }, { text: bText(3), callback_data: bCallback(3) }],
    [{ text: bText(4), callback_data: bCallback(4) }, { text: bText(5), callback_data: bCallback(5) }],
    [{ text: bText(6), callback_data: bCallback(6) }],
    [{ text: '🔍 Искать другие', callback_data: 'search_more' }]
  ]
};
return [{ json: result }];

const original = $('Format Telegram Topic Digest').first().json;
const recipients = [String(original.chat_id), '100000001'];
const unique = [...new Set(recipients.filter(id => id && /^-?\d+$/.test(id)))];
return unique.map(chatId => ({ json: { ...original, chat_id: chatId } }));
